import React from 'react';
import { Alert, Typography } from '@mui/material';
import { PageCard } from '@/components/PageCard';
import { PageLoader } from '@/components/ui/PageLoader';
import { useSelectedEventContext } from '@/hooks/useSelectedEventContext';
import { GetUserId, GetUserRoles } from '@/utils/token';
import { isEventOwner } from '@/utils/eventAccess';

/**
 * Renders children only for owners of the selected event, otherwise explains why the page
 * is unavailable. Event ownership is data on the event (its `owners` list), not a role, so
 * it cannot be expressed as a route role requirement.
 */
export const EventOwnerOnly: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { selectedEvent } = useSelectedEventContext();
    const userId = GetUserId();
    const userRoles = GetUserRoles();

    // PageTabs shows its own "No Event Selected" prompt before rendering children,
    // so a brief null event here just means the context has not loaded yet.
    if (!selectedEvent) return <PageLoader />;

    if (!isEventOwner(selectedEvent, userId, userRoles)) {
        return (
            <PageCard>
                <Alert severity="info">
                    <Typography variant="h6" gutterBottom>
                        Event Owner Access Required
                    </Typography>
                    <Typography>
                        This page is available only to owners of <strong>{selectedEvent.title}</strong>.
                        Ask an existing owner to add you to the event, or switch to an event you own.
                    </Typography>
                </Alert>
            </PageCard>
        );
    }

    return <>{children}</>;
};
